// BUILT §309 — SUBSTITUTE PARTS ON THE PARTS LIST. Pure: no three.js, no DOM, so the
// page, the CSV and the probe read one module.
//
// For a parts-list line (an LDraw part in a colour) this answers: which Rebrickable
// alternates and mould variants of the part were offered (src/technic-rebrickable.js,
// generated from Rebrickable's and BrickLink's downloads), which the model ACCEPTS in its
// place (src/technic-substitutes-verdicts.js, generated by running every judge the model
// has with the candidate's geometry swapped in), which it refused and by which judge, and
// which it could not judge and why. Nothing here judges: it only reads the two files.
//
// THE COLOUR. A passing substitute is offered in the line's colour when BrickLink lists an
// element for it in that colour; otherwise in the role-table colour BrickLink lists it in
// that the most official sets used (Rebrickable's count), and the line says it is a colour
// change. A candidate BrickLink lists in no role-table colour never reaches the geometry
// (its verdict is `bricklink`).
//
// THE COUNT IS NOT STOCK. "Used in N official sets in this colour" counts the sets whose
// Rebrickable inventory lists that part in that colour (spares excluded). It is how common
// the element was in LEGO's own sets — an abundance proxy — and says nothing about what is
// for sale. MODELLED, not built: a substitute that passes is one whose geometry every judge
// of the model accepts; nobody has built the model with it.
import { REBRICKABLE } from './technic-rebrickable.js';
import { SUBSTITUTE_VERDICTS } from './technic-substitutes-verdicts.js';
import { BRICKLINK } from './technic-bricklink.js';

export const SUBSTITUTE_SOURCE = `Rebrickable full download of ${REBRICKABLE.source.date}; ${REBRICKABLE.source.bricklink}`;
export const ABUNDANCE_DATE = REBRICKABLE.source.date;
export const usedIn = (n) => `used in ${n} official set${n === 1 ? '' : 's'} in this colour (Rebrickable, ${ABUNDANCE_DATE})`;
export const SUBSTITUTE_HONESTY = `An alternative is a Rebrickable alternate or mould variant of the part that every judge of the model accepts in its place, with nothing else changed (modelled, not built). "Used in N official sets" counts Rebrickable's set inventories as of ${ABUNDANCE_DATE}: how common the element was in LEGO's sets, not stock. A pin whose friction differs is not judged: friction is not modelled.`;
const colourName = (code) => BRICKLINK.colours[code]?.name ?? String(code);

// The colour a substitute is offered in for a line in `colour`, and whether it is a change.
export function offerColour(c, colour) {
  const els = c.bricklink?.elements ?? {};
  if ((els[colour] ?? []).length) return { code: Number(colour), change: false };
  const listed = Object.keys(els).filter((k) => (els[k] ?? []).length).map(Number);
  if (!listed.length) return null;
  listed.sort((a, b) => (c.abundance?.[b] ?? 0) - (c.abundance?.[a] ?? 0) || a - b);
  return { code: listed[0], change: true };
}

// Every candidate for one line, sorted into passed / failed / not judged. A line belongs to one build (`cell`): a
// candidate that reached the geometry is judged there by the judges that build calls for (the verdict's `cells`), so a
// part the alarm refuses may still be the keyless works'. With no cell, the verdict over every build the part is in.
export function substitutesFor(part, colour, cell = null) {
  const line = REBRICKABLE.lines[part], vs = SUBSTITUTE_VERDICTS.verdicts[part] ?? [];
  const out = { part, colour: Number(colour), placedAbundance: line?.abundance?.[colour] ?? 0, candidates: 0, passed: [], failed: [], notJudged: [] };
  if (!line) return out;
  for (const v of vs) {
    if (v.status === 'skip') continue;
    const c = line.candidates.find((x) => x.ldraw === v.candidate && x.rb === v.rb);
    if (!c) throw new Error(`technic-substitutes: verdict ${part}=${v.candidate} names no candidate in the subset`);
    out.candidates++;
    if (cell && v.cells && !v.cells[cell]) throw new Error(`technic-substitutes: verdict ${part}=${v.candidate} has no judgement for ${cell}`);
    const w = (cell && v.cells?.[cell]) || v;
    const oc = offerColour(c, colour);
    const row = { ldraw: c.ldraw, rb: c.rb, rel: c.rel, dir: c.dir, name: c.name, bricklink: c.bricklink ? { item: c.bricklink.number, name: c.bricklink.name } : null,
      sameItem: v.sameItem, judge: w.judge, detail: w.detail, cell: cell && v.cells ? cell : null,
      offer: oc && { code: oc.code, change: oc.change, colour: colourName(oc.code), bricklinkColourId: BRICKLINK.colours[oc.code]?.id ?? null, elements: c.bricklink.elements[oc.code], abundance: c.abundance?.[oc.code] ?? 0 } };
    (w.status === 'pass' ? out.passed : w.status === 'fail' ? out.failed : out.notJudged).push(row);
  }
  for (const k of ['passed', 'failed', 'notJudged']) out[k].sort((a, b) => (b.offer?.abundance ?? 0) - (a.offer?.abundance ?? 0) || (a.ldraw < b.ldraw ? -1 : 1));
  return out;
}

// One passing substitute, as a short sentence (the page's note and the CSV's cell).
export function alternativeText(s, line) {
  const o = s.offer, bl = s.bricklink;
  const colour = o.change ? `in ${o.colour} (a colour change from ${colourName(line.colour)})` : `in ${o.colour}`;
  const same = s.sameItem ? `; BrickLink sells it as the same item ${bl.item}, so a lot may be either mould` : '';
  return `${s.ldraw} ${s.name} (BrickLink ${bl.item}) ${colour}, ${usedIn(o.abundance)}${same}`;
}
// The line's summary of what was asked: counts, and each refusal by its judge.
export function judgedText(r) {
  if (!r.candidates) return 'no Rebrickable alternate or mould variant';
  const fails = r.failed.map((f) => `${f.ldraw}: ${f.judge}`), nj = r.notJudged.map((f) => `${f.ldraw}: ${f.judge}`);
  return `${r.candidates} candidate${r.candidates === 1 ? '' : 's'}: ${r.passed.length} passed${fails.length ? `, ${fails.length} failed (${fails.join('; ')})` : ''}${nj.length ? `, ${nj.length} not judged (${nj.join('; ')})` : ''}`;
}
// A warning the line itself owes: BrickLink sells a mould the model refuses under the line's own item.
export function sameItemWarnings(r) {
  return [...r.failed, ...r.notJudged].filter((f) => f.sameItem).map((f) => `BrickLink sells ${f.ldraw} under this line's own item ${f.bricklink.item}, and the model ${r.failed.includes(f) ? `refuses it (${f.judge})` : `could not judge it (${f.judge})`}: a lot may hold that mould`);
}
